statement:
You start with the integer array `arr` and transform it once per day. Each day's array is built from the previous day's array, with every element looking at its neighbours' values from that previous day:

- an element strictly smaller than both its left and right neighbours goes up by 1;
- an element strictly larger than both its left and right neighbours goes down by 1;
- every other element keeps its value, and the first and last elements never change.

Eventually a day passes on which nothing changes. Return the array at that point.

validator:
function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 100) return 'arr needs 1 to 100 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each value is an integer from 1 to 100.';
  return null;
}

reference:
function transformArray(arr) {
  let current = arr.slice();
  let changed = true;
  while (changed) {
    changed = false;
    const next = current.slice();
    for (let i = 1; i < current.length - 1; i++) {
      if (current[i] < current[i - 1] && current[i] < current[i + 1]) {
        next[i]++;
        changed = true;
      } else if (current[i] > current[i - 1] && current[i] > current[i + 1]) {
        next[i]--;
        changed = true;
      }
    }
    current = next;
  }
  return current;
}

brute:
function transformArray(arr) {
  // Apply one day with map and recurse until the array stops changing.
  const day = arr.map((v, i, a) => {
    if (i === 0 || i === a.length - 1) return v;
    return v + (v < Math.min(a[i - 1], a[i + 1]) ? 1 : 0) - (v > Math.max(a[i - 1], a[i + 1]) ? 1 : 0);
  });
  return day.join() === arr.join() ? day : transformArray(day);
}

