function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 9);
  const top = size === 'large' ? 100 : [3, 6, 20, 100][Math.floor(rand() * 4)];
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
